module WeightQuerySolver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] arr [0:7],\n    output reg [7:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] S_IDLE = 3'd0;\n    localparam [2:0] S_COUNT_FREQ = 3'd1;\n    localparam [2:0] S_INIT_DP = 3'd2;\n    localparam [2:0] S_COMPUTE_DP = 3'd3;\n    localparam [2:0] S_CHECK_RESULTS = 3'd4;\n    localparam [2:0] S_DONE = 3'd5;\n\n    reg [2:0] current_state, next_state;\n\n    // Frequency array (0-15 values)\n    reg [7:0] freq [0:15];\n    reg [15:0] total_sum;\n\n    // DP arrays\n    reg [7:0] dp_current [0:127][0:8];\n    reg [7:0] dp_next [0:127][0:8];\n\n    // Binomial coefficients (n=0-7, k=0-7)\n    reg [7:0] binom [0:7][0:7];\n\n    // Counters\n    reg [2:0] element_count;      // 0-7\n    reg [2:0] weight_index;       // 0-7\n    reg [3:0] v_count;            // 0-15\n    reg [2:0] i_count;            // 1-8\n    reg [7:0] current_max;        // 0-255\n\n    integer i, j, s, c, n, k;\n\n    // Combinational DP update\n    always @(*) begin\n        // Default assignment\n        for (i = 0; i < 128; i = i + 1) begin\n            for (j = 0; j < 9; j = j + 1) begin\n                dp_next[i][j] = dp_current[i][j];\n            end\n        end\n\n        // Update DP for current weight index\n        if (current_state == S_COMPUTE_DP && weight_index < 8) begin\n            automatic logic [3:0] w = arr[weight_index][3:0];\n\n            for (s = w; s < 128; s = s + 1) begin\n                for (c = 1; c < 9; c = c + 1) begin\n                    if (s >= w) begin\n                        dp_next[s][c] = dp_current[s][c] + dp_current[s - w][c - 1];\n                    end\n                end\n            end\n        end\n    end\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= 8'd0;\n            total_sum <= 16'd0;\n            element_count <= 3'd0;\n            weight_index <= 3'd0;\n            v_count <= 4'd0;\n            i_count <= 3'd0;\n            current_max <= 8'd0;\n            current_state <= S_IDLE;\n\n            // Initialize freq array\n            for (i = 0; i < 16; i = i + 1) freq[i] <= 8'd0;\n\n            // Initialize DP arrays\n            for (i = 0; i < 128; i = i + 1) begin\n                for (j = 0; j < 9; j = j + 1) begin\n                    dp_current[i][j] <= 8'd0;\n                end\n            end\n\n            // Precompute binomial coefficients\n            for (n = 0; n < 8; n = n + 1) begin\n                for (k = 0; k < 8; k = k + 1) begin\n                    case (n)\n                        0: binom[n][k] <= (k == 0) ? 8'd1 : 8'd0;\n                        1: binom[n][k] <= (k <= 1) ? 8'd1 : 8'd0;\n                        2: case (k)\n                                0: binom[n][k] <= 8'd1;\n                                1: binom[n][k] <= 8'd2;\n                                2: binom[n][k] <= 8'd1;\n                                default: binom[n][k] <= 8'd0;\n                            endcase\n                        3: case (k)\n                                0: binom[n][k] <= 8'd1;\n                                1: binom[n][k] <= 8'd3;\n                                2: binom[n][k] <= 8'd3;\n                                3: binom[n][k] <= 8'd1;\n                                default: binom[n][k] <= 8'd0;\n                            endcase\n                        4: case (k)\n                                0: binom[n][k] <= 8'd1;\n                                1: binom[n][k] <= 8'd4;\n                                2: binom[n][k] <= 8'd6;\n                                3: binom[n][k] <= 8'd4;\n                                4: binom[n][k] <= 8'd1;\n                                default: binom[n][k] <= 8'd0;\n                            endcase\n                        5: case (k)\n                                0: binom[n][k] <= 8'd1;\n                                1: binom[n][k] <= 8'd5;\n                                2: binom[n][k] <= 8'd10;\n                                3: binom[n][k] <= 8'd10;\n                                4: binom[n][k] <= 8'd5;\n                                5: binom[n][k] <= 8'd1;\n                                default: binom[n][k] <= 8'd0;\n                            endcase\n                        6: case (k)\n                                0: binom[n][k] <= 8'd1;\n                                1: binom[n][k] <= 8'd6;\n                                2: binom[n][k] <= 8'd15;\n                                3: binom[n][k] <= 8'd20;\n                                4: binom[n][k] <= 8'd15;\n                                5: binom[n][k] <= 8'd6;\n                                6: binom[n][k] <= 8'd1;\n                                default: binom[n][k] <= 8'd0;\n                            endcase\n                        7: case (k)\n                                0: binom[n][k] <= 8'd1;\n                                1: binom[n][k] <= 8'd7;\n                                2: binom[n][k] <= 8'd21;\n                                3: binom[n][k] <= 8'd35;\n                                4: binom[n][k] <= 8'd35;\n                                5: binom[n][k] <= 8'd21;\n                                6: binom[n][k] <= 8'd7;\n                                7: binom[n][k] <= 8'd1;\n                                default: binom[n][k] <= 8'd0;\n                            endcase\n                        default: for (k = 0; k < 8; k = k + 1) binom[n][k] <= 8'd0;\n                    endcase\n                end\n            end\n        end\n        else begin\n            current_state <= next_state;\n            done <= 1'b0;\n\n            case (current_state)\n                S_IDLE: begin\n                    result <= 8'd0;\n                    if (start) begin\n                        total_sum <= 16'd0;\n                        element_count <= 3'd0;\n                        // Reset freq array\n                        for (i = 0; i < 16; i = i + 1) freq[i] <= 8'd0;\n                        next_state <= S_COUNT_FREQ;\n                    end\n                end\n\n                S_COUNT_FREQ: begin\n                    automatic logic [3:0] val = arr[element_count][3:0];\n                    freq[val] <= freq[val] + 8'd1;\n                    total_sum <= total_sum + {12'd0, val};\n\n                    if (element_count == 3'd7) begin\n                        next_state <= S_INIT_DP;\n                    end\n                    else begin\n                        element_count <= element_count + 3'd1;\n                    end\n                end\n\n                S_INIT_DP: begin\n                    // Initialize DP table\n                    for (i = 0; i < 128; i = i + 1) begin\n                        for (j = 0; j < 9; j = j + 1) begin\n                            if (i == 0 && j == 0) dp_current[i][j] <= 8'd1;\n                            else dp_current[i][j] <= 8'd0;\n                        end\n                    end\n                    weight_index <= 3'd0;\n                    next_state <= S_COMPUTE_DP;\n                end\n\n                S_COMPUTE_DP: begin\n                    dp_current <= dp_next;\n\n                    if (weight_index == 3'd7) begin\n                        next_state <= S_CHECK_RESULTS;\n                        v_count <= 4'd0;\n                        i_count <= 3'd1;\n                        current_max <= 8'd0;\n                    end\n                    else begin\n                        weight_index <= weight_index + 3'd1;\n                    end\n                end\n\n                S_CHECK_RESULTS: begin\n                    automatic logic [3:0] v = v_count;\n                    automatic logic [2:0] i = i_count;\n                    automatic logic [7:0] f = freq[v];\n                    automatic logic [7:0] binom_val = (i <= f) ? binom[f][i] : 8'd0;\n                    automatic logic [15:0] vi = v * i;\n                    automatic logic [15:0] target_sum = (total_sum > vi) ? total_sum - vi : 16'd0;\n\n                    if (i <= f) begin\n                        automatic logic [7:0] dp_val1 = (vi < 128) ? dp_current[vi][i] : 8'd0;\n                        automatic logic [7:0] dp_val2 = (target_sum < 128) ? dp_current[target_sum][8-i] : 8'd0;\n                        if (dp_val1 == binom_val || dp_val2 == binom_val) begin\n                            if (i > current_max) current_max <= i;\n                        end\n                    end\n\n                    // Counter increment logic\n                    if (v_count == 4'd15 && i_count == 3'd8) begin\n                        result <= current_max;\n                        next_state <= S_DONE;\n                    end\n                    else if (i_count == 3'd8) begin\n                        v_count <= v_count + 4'd1;\n                        i_count <= 3'd1;\n                    end\n                    else begin\n                        i_count <= i_count + 3'd1;\n                    end\n                end\n\n                S_DONE: begin\n                    done <= 1'b1;\n                    next_state <= S_IDLE;\n                end\n\n                default: next_state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule